# ---------------------------------------------------------------------------
# Audit
# ---------------------------------------------------------------------------

def _check_cycle(cyc, K, meas):
    """Validate a negative-cycle inconsistency proof."""
    if not isinstance(cyc, list):
        return False
    n = len(cyc)
    if n < 1 or n > K:
        return False
    M = len(meas)
    total = 0
    first_src = None
    prev_dst = None
    for e in cyc:
        if not is_int(e) or e < 0 or e >= 2 * M:
            return False
        i, dirc = divmod(e, 2)
        a, b, lo, hi = meas[i]
        if dirc == 0:
            s, t, w = a, b, hi
        else:
            s, t, w = b, a, -lo
        if first_src is None:
            first_src = s
        elif s != prev_dst:
            return False
        prev_dst = t
        total += w
    if prev_dst != first_src:
        return False
    return total < 0


def _check_cal_cert(art, K, meas):
    """Independently verify a feasible calibration certificate."""
    if not isinstance(art, dict):
        return False
    if art.get('status') != 'ok':
        return False
    up = art.get('upper_ps')
    pr = art.get('pred')
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    M = len(meas)
    for a in range(K):
        row = up[a]
        prow = pr[a]
        if not isinstance(row, list) or len(row) != K:
            return False
        if not isinstance(prow, list) or len(prow) != K:
            return False
        if not is_int(row[a]) or row[a] != 0:
            return False
        if prow[a] is not None:
            return False
        for b in range(K):
            if not is_int(row[b]):
                return False
            if b == a:
                continue
            cell = prow[b]
            if not is_int(cell) or cell < 0 or cell >= 2 * M:
                return False
            i, dirc = divmod(cell, 2)
            x, y, lo, hi = meas[i]
            if dirc == 0:
                if y != b:
                    return False
            else:
                if x != b:
                    return False
    # every row is a feasible bias vector with its source entry zero
    for a in range(K):
        row = up[a]
        for (x, y, lo, hi) in meas:
            d = row[y] - row[x]
            if d < lo or d > hi:
                return False
    # predecessor chains reach the source and sum to the claimed bound
    for a in range(K):
        row = up[a]
        prow = pr[a]
        state = [0] * K
        accw = [0] * K
        state[a] = 2
        for b in range(K):
            if b == a or state[b] != 0:
                continue
            path = []
            cur = b
            while state[cur] == 0:
                e = prow[cur]
                i, dirc = divmod(e, 2)
                x, y, lo, hi = meas[i]
                w = hi if dirc == 0 else -lo
                nxt = x if dirc == 0 else y
                path.append((cur, w))
                state[cur] = 1
                cur = nxt
            if state[cur] != 2:
                return False
            total = accw[cur]
            for (node, w) in reversed(path):
                total += w
                accw[node] = total
                state[node] = 2
        for b in range(K):
            if b != a and accw[b] != row[b]:
                return False
    return True


def audit(profile, fabric, proposal):
    """Audit a structurally typed plan artifact."""
    K = int(profile['groups'])
    meas = [(int(m[0]), int(m[1]), int(m[2]), int(m[3]))
            for m in profile['measurements']]
    if not isinstance(proposal, dict):
        return {'valid': False}
    st = proposal.get('status')
    if st == 'inconsistent':
        return {'valid': _check_cycle(proposal.get('cycle'), K, meas)}
    if st != 'ok':
        return {'valid': False}
    if not _check_cal_cert(proposal.get('profile'), K, meas):
        return {'valid': False}
    calib = Calibration(profile)
    if calib.status != 'ok':
        return {'valid': False}
    fab = Fabric(fabric, calib)
    P = fab.P
    N = fab.N
    V = P * N
    if not is_int(proposal.get('period_rounds')) or \
            proposal.get('period_rounds') != P:
        return {'valid': False}
    peaks, chosen = fab.peaks_and_choice()
    ppeaks = proposal.get('peaks_as')
    if not isinstance(ppeaks, list) or len(ppeaks) != len(fab.guards):
        return {'valid': False}
    for idx in range(len(fab.guards)):
        pk = ppeaks[idx]
        op = peaks[idx]
        if pk is None:
            if op is not None:
                return {'valid': False}
        else:
            if not is_int(pk) or op is None or pk != op:
                return {'valid': False}
    pg = proposal.get('guard_ns')
    if pg is None:
        if chosen is not None:
            return {'valid': False}
        for key in ('bounds_as', 'age_rounds', 'pred', 'warmup_cycle'):
            if proposal.get(key) is not None:
                return {'valid': False}
        return {'valid': True}
    if not is_int(pg) or chosen is None or pg != chosen:
        return {'valid': False}
    g = chosen
    # ---- matrices -------------------------------------------------------
    pb = proposal.get('bounds_as')
    pa = proposal.get('age_rounds')
    pp = proposal.get('pred')
    if not isinstance(pb, list) or len(pb) != P:
        return {'valid': False}
    if not isinstance(pa, list) or len(pa) != P:
        return {'valid': False}
    if not isinstance(pp, list) or len(pp) != V:
        return {'valid': False}
    B = [None] * V
    A = [None] * V
    PR = [None] * V
    for p in range(P):
        rb = pb[p]
        ra = pa[p]
        if not isinstance(rb, list) or len(rb) != N:
            return {'valid': False}
        if not isinstance(ra, list) or len(ra) != N:
            return {'valid': False}
        base = p * N
        for i in range(N):
            b = rb[i]
            a = ra[i]
            if b is None and a is None:
                continue
            if b is None or a is None:
                return {'valid': False}
            if not is_int(b) or not is_int(a):
                return {'valid': False}
            if b < 0 or a < 0:
                return {'valid': False}
            B[base + i] = b
            A[base + i] = a
    for u in range(V):
        c = pp[u]
        if c is None:
            continue
        if not isinstance(c, list) or len(c) != 2:
            return {'valid': False}
        pv = c[0]
        kind = c[1]
        if not is_int(pv) or not is_int(kind):
            return {'valid': False}
        if pv < 0 or pv >= V:
            return {'valid': False}
        PR[u] = (pv, kind)
    for u in range(V):
        p, i = divmod(u, N)
        if fab.is_anchor(i, p):
            if B[u] != 0 or A[u] != 0 or PR[u] is not None:
                return {'valid': False}
        elif B[u] is None:
            if PR[u] is not None:
                return {'valid': False}
        else:
            if PR[u] is None:
                return {'valid': False}
    # ---- witness chains --------------------------------------------------
    order = sorted((u for u in range(V) if B[u] is not None), key=lambda u: A[u])
    rooted = [False] * V
    vT = fab.vT
    for u in order:
        p, i = divmod(u, N)
        if fab.is_anchor(i, p):
            rooted[u] = True
            continue
        pv, kind = PR[u]
        if B[pv] is None:
            return {'valid': False}
        if kind == -1:
            pp2 = p - 1
            if pp2 < 0:
                pp2 += P
            if pv != pp2 * N + i:
                return {'valid': False}
            cost = vT[i][pp2]
            inc = 1
        elif 0 <= kind < 2 * fab.NL:
            psrc = pv // N
            info = fab.step_info(psrc, kind, g)
            if info is None:
                return {'valid': False}
            dest, cost, inc = info
            if dest != u:
                return {'valid': False}
            if fab.codedata[kind][0] != pv - psrc * N:
                return {'valid': False}
        else:
            return {'valid': False}
        if B[u] != B[pv] + cost or A[u] != A[pv] + inc:
            return {'valid': False}
        rooted[u] = rooted[pv]
    for u in range(V):
        if B[u] is not None and not rooted[u]:
            return {'valid': False}
    # ---- certificate inequalities ---------------------------------------
    gthresh = g * fab.NCODE
    out = fab.out
    if out is None:
        fab.build_edges()
        out = fab.out
    for u in order:
        p, i = divmod(u, N)
        nd = p + N + i if p + 1 < P else i
        if B[nd] is None:
            return {'valid': False}
        if B[nd] > B[u] + vT[i][p] or \
                (B[nd] == B[u] + vT[i][p] and A[nd] > A[u] + 1):
            return {'valid': False}
        lst = out[u]
        if lst:
            bu = B[u]
            au = A[u]
            for dest, key, gc in lst:
                if gc < gthresh:
                    continue
                if B[dest] is None:
                    return {'valid': False}
                nb = bu + (key >> SHIFT)
                if B[dest] > nb or (B[dest] == nb and
                                    A[dest] > au + (key & AGE_MASK)):
                    return {'valid': False}
    # ---- safety and warmup ----------------------------------------------
    pk_sel = fab.peak_of_matrix(B)
    if pk_sel is None:
        return {'valid': False}
    if g * NS_AS < pk_sel + fab.reconfig * NS_AS:
        return {'valid': False}
    wk = proposal.get('warmup_cycle')
    if not is_int(wk) or wk != fab.warmup_of(A):
        return {'valid': False}
    return {'valid': True}


