def replay(profile, fabric, guard, trace):
    calib = Calibration(profile)
    if calib.status == 'inconsistent':
        return calib.artifact()
    fab = Fabric(fabric, calib)
    g = int(guard)
    N = fab.N
    T = fab.T
    P = fab.P
    R = int(trace['rounds'])
    rates = trace['rates_ppb']
    bias = [int(x) for x in trace['bias_ps']]
    sends = trace['sends']
    lost = set(int(x) for x in trace['lost'])
    reboots = trace['reboots']
    queries = [int(x) for x in trace['queries']]
    # group inputs by tick
    sends_by = {}
    sidx_of = {}
    send_status = [None] * len(sends)
    for idx, s in enumerate(sends):
        pid = int(s[0]); tick = int(s[1]); code = int(s[2]); jit = int(s[3])
        lst = sends_by.get(tick)
        if lst is None:
            lst = sends_by[tick] = []
        lst.append((pid, code, jit, idx))
    for tick in sends_by:
        sends_by[tick].sort()
    reb_by = {}
    for rb in reboots:
        tick = int(rb[0]); node = int(rb[1])
        lst = reb_by.get(tick)
        if lst is None:
            lst = reb_by[tick] = []
        lst.append(node)
    err = [None] * N
    bnd = [None] * N
    gen = [0] * N
    known = 0
    peak = 0
    delivered = 0
    adopted = 0
    unk_payloads = 0
    stale_payloads = 0
    pending = 0
    always = True
    states = {}
    qset = set(queries)
    adopted_id = [None] * N
    adopted_nodes = []
    due_at = {}
    codedata = fab.codedata
    codemeta = fab.codemeta
    vlist = fab.vlist
    vT = fab.vT
    blkmask = fab.blkmask
    for t in range(R + 1):
        # local drift up to this boundary
        if t > 0:
            rt = rates[t - 1]
            vp = fab.vTph[(t - 1) % P]
            for i in range(N):
                e = err[i]
                if e is None:
                    continue
                e = e + rt[i] * T
                err[i] = e
                bnd[i] = bnd[i] + vp[i]
                if e < 0:
                    if -e > peak:
                        peak = -e
                elif e > peak:
                    peak = e
        # reboot service
        rb = reb_by.get(t)
        if rb:
            for i in rb:
                gen[i] += 1
                if err[i] is not None:
                    err[i] = None
                    bnd[i] = None
                    known -= 1
        # anchor service
        an = fab.anch_nodes[t % P]
        if an:
            for i in an:
                if err[i] is None:
                    known += 1
                err[i] = 0
                bnd[i] = 0
        # due message applications
        due = due_at.get(t)
        if due:
            delivered += len(due)
            best = {}
            for pkt in due:
                (pid, sn, dn, sc, dc, j, m, partial, e0, b0, gs, gd,
                 jit) = pkt
                if gen[sn] != gs or gen[dn] != gd:
                    stale_payloads += 1
                    continue
                if e0 is None:
                    unk_payloads += 1
                    continue
                ae = rates[j - 1][dn] * partial
                ab = vlist[dn][(j - 1) % P] * partial
                for u2 in range(j, m):
                    r2 = rates[u2][dn]
                    ae += r2 * T
                    ab += vT[dn][u2 % P] * T
                ce = e0 + (bias[dc] - bias[sc]) * PS_AS + jit \
                    - codemeta[pid_code][2] if False else 0
                # (placeholder replaced below)
            # NOTE: real computation below
            best = {}
        # ---- sends --------------------------------------------------------
        ss = sends_by.get(t)
        if ss:
            ph = t % P
            q = fab.qp[ph]
            r = fab.rho[ph]
            slset = fab.slice_sets[q]
            wm = fab.winmask[ph]
            used = set()
            for (pid, code, jit, sidx) in ss:
                l = code >> 1
                if l >= fab.NL or l not in slset:
                    send_status[sidx] = 'not_in_slice'
                    continue
                sn, dn, j, partial, d, H, gbase = codedata[code]
                if blkmask[l] & wm[j]:
                    send_status[sidx] = 'blackout'
                    continue
                if r < g or r + g > gbase:
                    send_status[sidx] = 'guard'
                    continue
                port = (sn, codemeta[code][3])
                if port in used:
                    send_status[sidx] = 'port_busy'
                    continue
                used.add(port)
                if pid in lost:
                    send_status[sidx] = 'lost'
                    continue
                send_status[sidx] = 'sent'
                m = t + d
                if m <= R:
                    pktt = (pid, sn, dn, codemeta[code][0], codemeta[code][1],
                            t + j, m, partial, err[sn], bnd[sn], gen[sn],
                            gen[dn], jit)
                    lst = due_at.get(m)
                    if lst is None:
                        lst = due_at[m] = []
                    lst.append(pktt)
                else:
                    pending += 1
        # observed state (post service, pre send)
        if known != N:
            always = False
        if t in qset:
            states[t] = {'bounds_as': list(bnd), 'errors_as': list(err),
                         'adopted': list(adopted_id), 'generations': list(gen)}
        for i in adopted_nodes:
            adopted_id[i] = None
        del adopted_nodes[:]
    # apply remaining due packets (t == R already handled inside the loop)
    out_states = []
    for t in queries:
        st = states.get(t)
        if st is None:
            st = {'bounds_as': list(bnd), 'errors_as': list(err),
                  'adopted': list(adopted_id), 'generations': list(gen)}
        out_states.append(st)
    return {'status': 'ok', 'states': out_states,
            'send_status': send_status, 'delivered': delivered,
            'adopted': adopted, 'unknown_payloads': unk_payloads,
            'stale_payloads': stale_payloads, 'pending': pending,
            'peak_known_abs_as': peak, 'always_known': always}
